  'AI startup': 'AI初创公司',
  'ALARM: "{0}-memory" is in ALARM state.': '警报： "{0}-内存"处于警报状态。',
  'ALARM: "{0}-memory" is in ALARM state.\n\nReason: RAM fully used; the node is swapping.\n\nSuggested fixes, in no order:\n- Resize\n- Memory family\n- Shrink the pool\n\nYou are receiving this notice because you are a {1} customer, which you agreed to on page 41 of a document you did not read.':
    '警报： "{0}-内存"处于警报状态。\n\n原因：RAM完全使用；节点正在交换数据。\n\n建议修复方法（不排序）：\n- 重新调整大小\n- 内存类型\n- 缩小池\n\n您收到此通知是因为您是{1}客户，这是您在未阅读的文件第41页上同意的内容。',
  'ALARM: "{0}"': '警报： "{0}"',
  alert: '警报',
  'ALERT\n\nWhat limits the Design right now: {0}\nEverything else: has room to spare\n\nNo further detail in this alert. {1} is the narrow part of the pipe, and the rest of the Design waits on it.\n\n- {2}':
    '警报\n\n目前限制设计的是：{0}\n其他一切：仍有空间\n\n此警报中无更多细节。{1}是管道中的狭窄部分，设计的其余部分依赖它。\n\n- {2}',
  'ALERT {0} mem=100% swap=active': '警报 {0} 内存=100% 交换=活跃',
  'Alert fatigue report: "{0}"': '警报疲劳报告： "{0}"',
  'Alert fired': '警报已触发',
  'ALERT HEALTH REPORT': '健康警报报告',
  'ALERT HEALTH REPORT\n\nRule: {0}\nFalse alarms today: 5\nPeople still paying attention: 0\n\nAfter five false alarms in one day, your team now ignores this rule. A rule nobody reads is a very expensive comment.\n\nRecommended: change its threshold.\n\n{1}':
    '健康警报报告\n\n规则：{0}\n今日假警报：5\n仍有人关注：0\n\n一天内出现五次假警报后，您的团队现在忽略此规则。无人阅读的规则是非常昂贵的评论。\n\n建议：更改其阈值。\n\n{1}',
  'Alert ignored': '警报被忽略',
  'Alert rules': '警报规则',
  'ALERT TRIGGERED': '警报触发',
  'ALERT TRIGGERED\n\nComponent: Database\nCause: query with no index\nEffect: whole tables scanned\nAdd index: not available yet\n\nRemediation:\n- Research Query analysis, or\n- Put a Cache in front\n\n{0}':
    '警报触发\n\n组件：数据库\n原因：查询无索引\n影响：所有表都被扫描\n添加索引：尚未可用\n\n解决方案：\n- 研究查询分析，或\n- 在前方添加缓存\n\n{0}',
  'ALERT TRIGGERED\n\nComponent: Database\nCondition: query without an index\nEffect: whole tables scanned on every call\n\nRemediation: select the Database and click Add index.\n\nThis alert is easy to fix and hard to ignore. Please do the first one.\n{0}':
    '警报触发\n\n组件：数据库\n条件：查询无索引\n影响：每次调用时所有表都被扫描\n\n解决方案：选择数据库并点击添加索引。\n\n此警报容易修复且难以忽略。请执行第一步。\n{0}',
  'ALERT TRIGGERED\n\nComponent: Postgres\nError: refusing new connections\nCause: too many app processes holding pools\n\nRemediation:\n- Shrink pools, or\n- Add a Connection Pooler\n\nThis page will repeat until acknowledged by a human, a pet, or a cat walking across the keyboard.\n{0}':
    '警报触发\n\n组件：Postgres\n错误：拒绝新连接\n原因：太多应用进程占用池\n\n解决方案：\n- 缩小池，或\n- 添加连接池\n\n此页面会重复出现，直到有人、宠物或猫走过键盘后得到确认。\n{0}',
  "ALERT TRIGGERED\n\nRequests: {0}\nStatus: failing\nReason: writes need the primary Database\nNote: a replica can't take them\n\nCheck where your {1} requests are going. They must reach the primary.\n\nYou are receiving this because you are awake.\n{2}":
    '警报触发\n\n请求：{0}\n状态：失败\n原因：写入操作需要主数据库\n注意：副本无法接收这些请求\n\n检查您的{1}请求流向何处。它们必须到达主数据库。\n\n您之所以收到此消息，是因为您正在清醒。\n{2}',
  'ALERT TRIGGERED\n\nRequests: {0}\nStatus: failing\nSuggested action: check the links\n\nThis alert will escalate until {1} requests succeed again or the sun comes up, whichever happens first. Probably the sun.\n{2}':
    '警报触发\n\n请求：{0}\n状态：失败\n建议操作：检查链接\n\n此警报将持续升级，直到{1}次请求成功或太阳升起，以先者为准。很可能是太阳。\n{2}',
  'ALERT TRIGGERED\n\nService: {0}\nCondition: every worker busy\nCause: mostly waiting on the database\nPool setting: none on this runtime\nSuggested action: make the database answer faster\n\nThis alert will keep firing until a worker is free. {1} will keep telling you.':
    '警报触发\n\n服务：{0}\n条件：所有工作者繁忙\n原因：主要等待数据库\n运行时池设置：无\n建议操作：让数据库响应更快\n\n此警报将持续触发，直到有工作者空闲。{1}会持续通知您。',
  "ALERT TRIGGERED\n\nService: {0}\nCondition: requests above its throughput\nStatus: this is the limit\n\nThere's no setting in this alert to make the limit go away. {1} is doing all it can, and more is arriving.\n\n{2}\nYou are receiving this because you are awake.":
    '警报触发\n\n服务：{0}\n条件：请求超过其吞吐量\n状态：这是极限\n\n此警报中没有设置可以消除极限的方法。{1}已尽最大努力，更多请求仍在到来。\n\n{2}\n您之所以收到此消息，是因为您正在清醒。',
  'ALERT TRIGGERED\n\nService: {0}\nCondition: requests with nowhere to go\n\nRemediation: link {1} to something that takes them.\n\nShow on Board is attached. You are receiving this because you are awake.\n{2}':
    '警报触发\n\n服务：{0}\n条件：请求无处可去\n\n解决方案：将{1}链接到能够接收它们的东西。\n\n“显示在板上”已附随。您之所以收到此消息，是因为您正在清醒。\n{2}',
  "ALERT TRIGGERED\n\nService: {0}\nRuntime: {1}\nCondition: every worker busy\nMostly: waiting\n\nRemediation (pick one):\n1. Raise the pool\n2. Speed up the database\n\nIf nobody responds, this alert escalates to whoever is awake. Statistically, that's you.\n- {2}":
    '警报触发\n\n服务：{0}\n运行时：{1}\n条件：所有工作者繁忙\n主要：等待\n\n解决方案（选一）：\n1. 增加池\n2. 加快数据库速度\n\n如果无人响应，此警报将升级至清醒者。统计上，那就是您。\n- {2}',
  'ALERT TRIGGERED\n\nService: {0}\nStatus: FAILED\n\nRemediation:\n1. Select {1} and click Replace, or\n2. Wait for the provider\n\nUse Show on Board to find it.\n\nThis page will escalate until somebody does one of the above. You are receiving this because you are awake.\n{2}':
    '警报触发\n\n服务：{0}\n状态：失败\n\n解决方案：\n1. 选择{1}并点击替换，或\n2. 等待提供商\n\n使用“显示在板上”查找它。\n\n此页面会升级，直到有人执行上述操作之一。您之所以收到此消息，是因为您正在清醒。\n{2}',
  'Alert triggered: {0}': '警报触发：{0}',
  'Alert: {0}': '警报：{0}',
  'Alert: {0}\nDuration: {1} seconds\nUrgency: High': '警报：{0}\n持续时间：{1} 秒\n紧急程度：高',
