  'Annotation: {0} restart': '注释：{0}重启',
  'ANNOUNCEMENT\n\nWe\'re proud to share that {0} has completed its SOC 2 audit with zero findings.\n\nThe auditors could not locate any customer data, so none of it could be mishandled. They described our retention policy as "immediate" and our access controls as "moot".\n\nYour data has never been safer. Your data has never been anywhere.\n\nBook a security review with our team. Bring nothing; you\'ll leave with nothing.':
    '公告\n\n我们很自豪地宣布，{0}已完成SOC 2审计，且未发现任何问题。\n\n审计人员未能找到任何客户数据，因此无法出现任何数据泄露。他们称我们的保留政策为“即时”，访问控制为“无效”。\n\n你的数据从未更安全过。你的数据也从未在任何地方存在过。\n\n与我们的团队预约安全审查。什么都不带；你将空手而归。',
  'Annual fee: $299.00': '年费：299.00 美元',
  'Annual fee: $299.00\nBenefits: Unclear': '年费：299.00 美元\n优势：不明确',
  'Another deploy out the door: {0}.': '又一项部署完成：{0}。',
  'Another one done: {0}': '又完成一个：{0}',
  'Another one off the list: {0} is finished.': '又一项从清单中移除：{0}已完成。',
  "Another query without an index. Same story as last time: there's nothing to look rows up by, so every read scans the table from the first row to the last.":
    '又有一个没有索引的查询。和上次一样：没有可以按行查找的东西，所以每次读取都会从第一行扫描到最后一行。',
  'Answers cacheable pages near the user. Egress from the edge costs less.':
    '答案缓存用户附近的页面。从边缘端出发的成本更低。',
  'Answers read queries from memory while the hot data fits. Writes pass through and invalidate.':
    '答案读取查询时从内存中获取，只要热门数据仍在内存中即可。写入操作会触发无效化。',
  'Answers reads. Lags behind writes, so some API reads come back stale.':
    '答案读取。相对于写入操作有延迟，因此部分API读取返回的数据可能已过时。',
  'Answers report scans in columns. 1.5 s each, no limit, paid per scan.':
    '答案报告扫描结果以列形式显示。每个扫描1.5秒，无限制，按次收费。',
  'Answers search queries. 400 per second per size step.': '回答搜索查询。每个大小级别每秒400次。',
