  'Assigned to: you (you are the whole rotation)': '分配给：您（您负责全部轮班）',
  async: 'async',
  'Async I/O': '异步I/O',
  'Async tasks on every core, no GC, little memory. A CPU-heavy task blocks one worker thread.':
    '每个核心上的异步任务，无GC，占用内存少。CPU负载高的任务会阻塞一个工作线程。',
  "At {0} we do not invest in companies. We invest in decades. We have watched many Boards come and go, and yours has the quiet look of something that will still be running when our grandchildren's funds are raising.":
    '在 {0}，我们不投资公司。我们投资的是数十年。我们见证了众多董事会的兴衰，而您的董事会看起来像是那种即使我们孙辈的资金在筹集时也能继续运行的东西。',
  'At {0}, we help companies like {{company}} unlock {{benefit}} with the power of {{buzzword}}.':
    '在{0}，我们帮助像{{company}}这样的公司通过{{buzzword}}的力量解锁{{benefit}}。',
  'At approximately just now, {0} tried to use more memory than it had. Our systems responded the way systems do: the process was stopped and {1} restarted.':
    '大约就在刚才，{0} 尝试使用了超出其内存的额度。我们的系统响应方式与通常的系统一样：该进程被停止，并重新启动了 {1}。',
  'At most {0} teams.': '最多{0}个团队。',
  'At the current rate, {1} will spend its last CPU credit soon. Once it does, it will be held to 20% CPU.':
    '以当前速度，{1} 将很快耗尽最后一个 CPU 信用。耗尽后，CPU 使用率将限制在 20%。',
  'At the time of writing, a task in your queue has failed every attempt. Workers continue to retry it in preference to draining the queue. In the industry this is known as a poison message; in the office it is known as "why is everything stuck".':
    '在撰写此消息时，您队列中的一个任务已尝试多次失败。工作程序仍在优先重试该任务，而不是清空队列。业内称之为“毒消息”；办公室里则称为“为什么一切都卡住了”。',
  'At the user target, take or decline the round. Pre-seed brings writes, logins and incidents.':
    '在用户目标端，接受或拒绝轮询。预种子带来写入、登录和事件。',
  'At-least-once delivery': '至少一次交付',
  'Attack target: you': '攻击目标：您',
  'Attack type: HTTP flood, artisanal': '攻击类型：HTTP 洪流，手工制造',
  'Attention Required!': '注意！',
  'Attention Required!\n\nWhat happened?\nA flood of junk traffic is hitting your edge. None of these requests want to buy anything. They only want to arrive, all of them, at the same time.\n\nWhat can I do?\nIf you are a visitor: nothing. You are probably a toaster.\nIf you own the site: watch the Board and see how your Design takes a wave this size.\n\nRay ID: 8b0f13c7a2e9\nPerformance & security by {0}':
    '注意！\n\n发生了什么？\n大量垃圾流量正冲击您的边缘节点。这些请求中没有任何一个想要购买任何东西，它们只想同时抵达。\n\n我能做什么？\n如果您只是访客：无事可做。您可能只是一个烤面包机。\n如果您拥有该网站：观察“董事会”，看看您的“架构”如何应对如此规模的波动。\n\nRay ID: 8b0f13c7a2e9\n性能与安全由{0}提供',
  'Attention Required! Your edge is under attack': '注意！您的边缘节点正受到攻击',
