  'CREDIT FORECAST: FREE-TIER PROSPECT\n\nEstimated monthly credits: 3\nEstimated monthly credits after one curious analyst: 41,000\nEstimated monthly credits after one dashboard set to refresh every minute: yes\n\nRecommended plan: Enterprise Plus Platinum Snow\n\n{0} warehouses auto-suspend after 10 minutes idle. Dashboards are never idle.\n\nTo discuss your forecast, reply to this email. Replies are free.':
    '信用预测：免费层级展望\n\n预计每月信用额度：3\n预计每月信用额度（一位好奇分析师使用后）：41,000\n预计每月信用额度（若一个仪表盘设置为每分钟刷新一次）：是\n\n推荐方案：企业高级白金版Snow\n\n{0}仓库在闲置10分钟后自动暂停。仪表盘不会处于闲置状态。\n\n如需讨论您的预测，请回复此邮件。回复免费。',
  'Credit: Discovered by our research team, in the year 2104.':
    '来源：由我们的研究团队于 2104 年发现。',
