  'Event type: CPU_CREDITS_DRAINING': '事件类型：CPU_CREDITS_DRAINING',
  'Event type: CPU_CREDITS_DRAINING\nResource: {0}\nCategory: scheduled (by you, by accident)\nExpected impact: CPU capped at 20% when credits reach zero':
    '事件类型：CPU_CREDITS_DRAINING\n资源：{0}\n分类：预设（由您造成，意外）\n预期影响：信用数达零时，CPU 被限制在 20%',
  'Event type: CPU_CREDITS_DRAINING\nResource: {0}\nCategory: scheduled (by you, by accident)\nExpected impact: CPU capped at 20% when credits reach zero\n\nAvoid by: switching to General, or resizing.\n\nLocate: Show on Board.\n\nThis mailbox is unattended. So, it seems, is {1}.':
    '事件类型：CPU_CREDITS_DRAINING\n资源：{0}\n分类：预设（由您造成，意外）\n预期影响：信用数达零时，CPU 被限制在 20%\n\n避免方法：切换至 General，或调整规模。\n\n位置：显示在板块上。\n\n此邮箱无人看管。因此，似乎 {1} 也是如此。',
  'Event type: CPU_CREDITS_EXHAUSTED': '事件类型：CPU_CREDITS_EXHAUSTED',
  'Event type: CPU_CREDITS_EXHAUSTED\nResource: {0}\nStatus: Open\nImpact: CPU capped at 20%':
    '事件类型：CPU_CREDITS_EXHAUSTED\n资源：{0}\n状态：开放\n影响：CPU 被限制在 20%',
  'Event type: CPU_CREDITS_EXHAUSTED\nResource: {0}\nStatus: Open\nImpact: CPU capped at 20%\n\nDescription: This Burstable resource spends credits above 20% of each core and earns them below it. The balance is now zero.\n\nResolution: Resize the resource, or change its family from Burstable (for example, to General).\n\nNo reply is necessary. No reply is possible.':
    '事件类型：CPU_CREDITS_EXHAUSTED\n资源：{0}\n状态：开放\n影响：CPU 被限制在 20%\n\n描述：此 Burstable 资源的信用数每次核心使用量超过 20%，而获得的信用数则低於此比例。现在余额为零。\n\n解决方法：调整资源规模，或将其类型从 Burstable 更改（例如，更改至 General）。\n\n无需回覆。无法回覆。',
  'Event type: DISK_READS_ELEVATED': '事件类型：DISK_READS_ELEVATED',
  'Event type: DISK_READS_ELEVATED\nAffected resource: {0}\nCause: Working set exceeds available RAM.\nEffect: Reads go to disk.':
    '事件类型：DISK_READS_ELEVATED\n受影响资源：{0}\n原因：工作集超出可用 RAM。\n影响：读取操作转至盘面。',
  'Event type: DISK_READS_ELEVATED\nAffected resource: {0}\nCause: Working set exceeds available RAM.\nEffect: Reads go to disk.\n\nTo resolve, Resize the resource or select the Memory family.\n\nThis is an automated message from {1}. Replies are routed to a folder that we sunset in a previous quarter.':
    '事件类型：DISK_READS_ELEVATED\n受影响资源：{0}\n原因：工作集超出可用 RAM。\n影响：读取操作转至盘面。\n\n要解决问题，请调整资源规模或选择 Memory 类型。\n\n此消息由 {1} 自动发送。回覆将被路由至一个我们前一个季度已终止使用的文件夹。',
  'Event type: OUT_OF_MEMORY_RESTART': '事件类型：OUT_OF_MEMORY_RESTART',
  'Event type: OUT_OF_MEMORY_RESTART\nAffected resource: {1}\nStatus: Closed (restarted)':
    '事件类型：OUT_OF_MEMORY_RESTART\n受影响的资源：{1}\n状态：已关闭（已重启）',
  'EVENT: CPU_CREDITS_DRAINING ({0})': '事件：CPU_CREDITS_DRAINING ({0})',
  'EVENT: CPU_CREDITS_EXHAUSTED ({0})': '事件：CPU_CREDITS_EXHAUSTED ({0})',
  'Event: DISK_READS_ELEVATED on {0}': '事件：DISK_READS_ELEVATED 发生於 {0}',
  'Event: MEMORY_EXHAUSTED_COLOCATED': '事件：MEMORY_EXHAUSTED_COLOCATED',
  'Event: MEMORY_EXHAUSTED_COLOCATED\nResource: {0}\nRoot cause: Postgres shares the box with the application. Combined memory exceeds RAM; the node is swapping.':
    '事件：MEMORY_EXHAUSTED_COLOCATED\n资源：{0}\n根本原因：Postgres与应用程序共享同一台服务器。合并后的内存超过RAM；节点正在进行交换。',
  'Event: MEMORY_EXHAUSTED_COLOCATED\nResource: {0}\nRoot cause: Postgres shares the box with the application. Combined memory exceeds RAM; the node is swapping.\n\nRemediation: Place a Database and link the node to it.\n\nThis notice was generated by {1}. It is not a contract, a promise, or a person.':
    '事件：MEMORY_EXHAUSTED_COLOCATED\n资源：{0}\n根本原因：Postgres与应用程序共享同一台服务器。合并后的内存超过RAM；节点正在进行交换。\n\n修复方法：放置一个数据库并将节点链接到它。\n\n此通知由{1}生成。它不是合同、承诺或人物。',
  'Event: out of memory': '事件：内存不足',
  'event:{0}': '事件:{0}',
