    '事件：仍在计数\n受影响用户：排队中的所有用户',
  'Eventual consistency': '最终一致性',
  'Every {0} worker on {1} is busy': '{1}上的每个{0}个工作单元都很忙',
  'Every {0} worker on {1} is busy, mostly waiting. Raise the pool, or speed up the database.':
    '{1}上的每个{0}个工作单元都很忙，主要是在等待。增加工作单元池，或加快数据库速度。',
  'Every {1} worker on {2} is taken. Most of them are just waiting, which is the most expensive kind of busy.':
    '{2}的每个{1}名员工都已到位。其中大多数人只是在等待，这是最昂贵的忙碌方式。',
  'Every advisory is critical until proven otherwise.':
    '所有建议性操作在证明相反之前都是关键操作。',
  'Every API read must see the latest write. Hold it for 2 minutes.':
    '每次API读取都必须看到最新的写入数据。保持2分钟。',
  'Every App Server has moved. Fix its bugs.': '所有应用服务器都已迁移。修复其漏洞。',
  'Every App Server runs Node.js.': '每个应用服务器都运行Node.js。',
  'Every App Server runs PHP': '每个应用服务器都运行PHP。',
  'Every build checks its libraries for known holes. Required for SOC 2.':
    '每次构建都会检查其库是否存在已知漏洞。这是SOC 2的要求。',
  'Every event counts. Every event is billed.': '每个事件都计为一次。每个事件都会产生费用。',
  'Every first deploy': '每次首次部署',
  "Every migration has a long middle where both Stacks are running and nobody can quite remember why the old one existed. You're in it.":
    '每一次迁移都会有一个漫长的中间阶段，两个技术栈都在运行，但没有人能完全记得为什麽旧的技术栈存在。你正处於其中。',
  'Every miss': '每次失败',
  "Every null pointer we've ever chased would simply not compile in Rust. I want that for us. I want that for the app servers.":
    '我们过去追逐过的每一个空指针在Rust中根本不会编译。我希望这样，也希望应用服务器能这样。',
  "Every other part is waiting on it. If you're wondering where to look first, look there.":
    '其他所有部分都在等待它。如果你想知道该先看哪里，就去看那里。',
  'Every panel for zone {0} just went flat': '区域{0}的每个面板刚刚变为空值',
  "Every payment that arrives while the drawer is full is lost. Click Payments to collect what's waiting, and new revenue will land again.":
    '在抽屉满时收到的每笔付款都会丢失。点击“付款”以收集等待的款项，新收入将再次到来。',
  'Every Playbook slot is full ({0}). Delete one, or buy more in the Legacy shop.':
    '每个架构方案槽位已满（{0}）。删除一个，或在Legacy商店购买更多。',
  'Every query has an index.': '每个查询都有索引。',
  'Every read now scans the whole table, row by row, like someone looking for their keys in every drawer of the house. Reads that took a blink now take a while, and the Database is doing all of it.':
    '现在每次读取都要扫描整个表，逐行进行，就像有人在家里的每个抽屉里寻找钥匙一样。原本眨眼间完成的读取现在需要很长时间，而数据库正在执行所有这些操作。',
  'Every request to {1} is failing, because {2} itself has failed.':
    '向{1}的每个请求都失败，因为{2}本身已经失败。',
  'Every round deserves a sequel.': '每一轮都值得续作。',
  "Every sale from here on lands on the floor next to the drawer instead of in it. It's the nicest problem a business can have, right up until it isn't.":
    '从今後，每一笔销售都会落在储金箱旁边的地板上，而不是放入其中。这是一家企业能遇到的最美好的问题，直到它不再美好为止。',
  'Every worker in the {2} pool is busy, and most are waiting rather than working.':
    '{2} 池中的所有工作单元都繁忙，其中大多数正在等待而非工作。',
  'Every worker on {0} is busy, mostly waiting on the database.':
    '{0} 中的每个工作者都很忙，主要是在等待数据库。',
  'Every write goes to the cache and the database together, so cached reads are never stale for those keys.':
    '每次写入都会同时发送到缓存和数据库，因此对于那些键而言，缓存读取永远不会过时。',
  'Everything else: has room to spare': '其他一切：仍有空间',
  "Everything is running and I haven't seen an error yet. I'll keep an eye on it through the afternoon.":
    '一切正常运行，目前尚未看到任何错误。我会在下午继续留意情况。',
  'Excited to get going. Point me at something.': '很期待开始工作。请给我指个方向。',
