  'FINAL NOTICE\n\nAccount: Your Company\nRegion: mars-north-1 (Olympus Mons Zone B)\nOutstanding: $7,000.00 + "fees"\n\nWe have tried to contact you multiple times about unpaid compute in the above region. If payment is not received within 24 hours, this account will be referred to our collections partner, who is very serious and wears a tie.\n\nTo resolve this matter, click "Pay invoice."\n\n{0} Legal & Billing Department':
    '最终通知\n\n账户：您的公司\n区域：mars-north-1（奥林匹斯山B区）\n未付款金额：$7,000.00 + “费用”\n\n我们已多次尝试联系您，以解决该区域未支付的计算费用问题。若24小时内仍未收到付款，此账户将被转交给我们催收合作伙伴，他们会非常严肃并佩戴领带。\n\n为了解决此事，请单击“支付发票”。\n\n{0} 法律与账单部门',
