  'Firing\n\nRule: {0}\nFor: {1}s\nSeverity: page\n\nThis rule has been true for {2} seconds, which is long enough to count and too long to ignore.\n\nYour graph is doing something. That is not good.\n\n{3}':
    '触发\n\n规则：{0}\n针对：{1}秒\n严重性：页面\n\n此规则已持续{2}秒，时间足够计数，但过长可忽略。\n\n您的图表正在执行某些操作。这并非好事。\n\n{3}',
