  'Gooble Cloud Platypus': 'Gooble Cloud Platypus',
  "Good morning (it's always morning somewhere on call),": '早上好（通话中某个地方总是早上）',
  "Good morning (it's always morning somewhere on call),\n\nThe Cache restarted, and it came back remembering nothing. That's normal for a cache. What isn't fun is what happens next: every request misses, and every miss goes to the Database.\n\nPicture a library where the front desk forgot every answer, so everyone walks to the archive at once. The archive is your Database.\n\nRegards,\n{0} Incident Response":
    '早上好（通话中某个地方总是早上）\n\n缓存已重启，但已忘记所有内容。这是缓存的正常现象。不愉快的是接下来会发生什么：每个请求都会失败，每个失败都会转至数据库。\n\n想象一个图书馆，前台忘记了所有答案，于是所有人都同时前往档案室。档案室就是你的数据库。\n\n此致,\n{0} 事件响应团队',
  'Good news, for once: {0} is over. The graphs are back to the shapes you like. Not flat, not cliffs, just lines.':
    '好消息，这次终于来了：{0} 结束了。图表已恢复您喜欢的形状。不是平坦的，也不是陡峭的悬崖，只是直线。',
  "Good news: {0} is still running. Less good news: it's out of CPU credits, so it's throttled to 20%.":
    '好消息：{0} 仍在运行。坏消息：它已耗尽 CPU 信用额度，因此被限制到 20%。',
  "Good news: this one's in your hands. Select the Database and click Add index.":
    '好消息：这个查询现在在您手中。选择数据库并点击添加索引。',
  'Good news!': '好消息！',
  "Good news!\n\nYour team is eligible for a 14-day free trial of {0} Enterprise.\n\nWhat's included:\n- Unlimited dashboards\n- Unlimited alerts about your dashboards\n- A dashboard of your alerts about your dashboards\n- Custom metrics, billed per custom metric, per host, per hour, per feeling\n\n*After 14 days, your data stays with us. You can export it any time by talking to Sales.\n\nStart your trial in one click!\n\nThe {1} Growth Team":
    '好消息！\n\n您的团队有资格获得 {0} Enterprise 的 14 天免费试用。\n\n包含内容：\n- 无限仪表盘\n- 无限关于您仪表盘的警报\n- 一个显示您警报的仪表盘\n- 自定义指标，按自定义指标、主机、小时、感受计费\n\n*14 天后，您的数据将保留在我们这里。您可以随时与销售部门联系进行导出。\n\n一键开始试用！\n\n{1} 增长团队',
  'Goodnight, probably.': '晚安，可能吧。',
  'Goroutines for the app servers': '适用于应用服务器的 Goroutines',
  'Goroutines on every core. Waiting costs a few KB, not a worker. GC takes CPU when the heap is full.':
    '每个核心上的 Goroutines。等待会消耗几 KB，而非一个工作者。当堆满时，GC 会占用 CPU。',
  'GOTO statements considered harmful, as are your SLOs.':
    'GOTO 语句被认为有害，您的 SLO 也是如此。',
