  'Great news from {0}: people really want to download things from {1}. So many that its network card is now sending bytes as fast as it physically can.':
    '来自 {0} 的好消息：人们确实很想从 {1} 下载内容。数量如此之多，以至于其网络卡现在能以物理极限速度发送字节。',
  "Great news: you've made so much money that your Payments drawer is completely full! Less great news: new revenue has nowhere to go, so it is spilling, and spilled revenue is lost.":
    '好消息：您赚了很多钱，以至于 Payments 抽屉已经完全满了！不太好的消息是：新收入无处可去，因此正在溢出，溢出的收入会丢失。',
  "Great question! Reads are available on our Enterprise tier, priced per read, with a minimum commitment of three years. Our Sales Engineering team will be happy to explain what you'll be reading.":
    '非常好的问题！我们的企业版支持读取操作，按次收费，最低承诺三年。我们的销售工程团队会很乐意解释您会读取什么内容。',
  greedy: '贪婪',
  green: '绿色',
  'Green threads': '绿色线程',
  'Greetings from {0}!': '来自{0}的问候！',
  "Greetings from {0}!\n\nWe're excited to let you know that {1} has been enrolled in our Throttling experience. It ran out of CPU credits and now runs at 20% CPU.\n\nBackground: Burstable instances bank credits under 20% of each core and burn them over it.\n\nTo opt out of the experience, Resize {2} or switch it to a non-Burstable family such as General.\n\nWe'd love your feedback! Feedback is also in Preview.":
    '来自{0}的问候！\n\n我们很高兴地通知您，{1}已被纳入我们的节流体验。其CPU信用已用完，现在运行在20%的CPU上。\n\n背景：突发性实例会将每个核心的信用消耗在20%以下，并在超过该点后耗尽。\n\n要退出此体验，请重新调整{2}或将其切换为非突发性家族，例如General。\n\n我们期待您的反馈！反馈也已在预览中。',
  'grid-cols-4 narrow:grid-cols-2': 'grid-cols-4 narrow:grid-cols-2',
  group: '组',
  grow: '增长',
  Grow: '增长',
  'Grow a startup from one server in a garage to a public company, one real bottleneck at a time.':
    '从车库里的一台服务器起步，把初创公司发展成上市企业，逐步解决真实瓶颈。',
  'Grow a startup from one server in a garage to a public company. Wire components, pick stacks, and fix one real bottleneck after another in an incremental systems design game.':
    '从车库里的一台服务器起步，把初创公司发展成上市企业。连接组件、选择技术栈，逐步解决真实瓶颈。',
  'Grow to {0} users and clear the IPO checklist to go public.':
    '增长至{0}用户并清除IPO检查清单以公开上市。',
  'Grow to {0} users to raise the {1} round.': '增长至{0}用户以完成{1}轮融资。',
  'Grow to {0} users to raise the {1} round. Let your users make the argument. It is the only one investors cannot interrupt.':
    '增长到 {0} 个用户以发起 {1} 轮融资。让您的用户来提出论点。这是唯一投资者无法打断的论点。',
  'Grow to {0} users. Then raise the {1} round.': '增长到 {0} 用户。然后进行 {1} 轮融资。',
  'Grow to {1} users, and the {2} round will come to you. Until then, keep the Design healthy and the users happy.':
    '增长到 {1} 用户后，{2} 轮融资就会到来。在此之前，请保持“架构”健康，让用户满意。',
  'Grow to the next round': '增长至下一轮',
  Growth: '增长',
