  'Growth +10%, uploads arrive: 120 ms of CPU each': '增长+10%，上传到达时间：每个CPU 120毫秒',
  'Growth +15%, writes arrive early': '增长 +15%，写入信息提前到达',
  'Growth +15%. Notifications arrive, through the Push Provider':
    '增长 +15%. 通知通过推发提供商到达',
