  'Instance: {0}\nEvent: out of memory\nResult: restarted':
    '实例：{0}\n事件：内存不足\n结果：已重启',
  'Instance: {0}\nEvent: out of memory\nResult: restarted\n\n{1} used all of its RAM, so the process was killed and the node restarted. This notice is informational. So, in a way, was the restart.\n\n{2} Compute Notifications':
    '实例：{0}\n事件：内存不足\n结果：已重启\n\n{1} 使用了全部 RAM，因此该进程被终止并重启了节点。此通知仅为信息性提示。换句话说，这确实是一次重启。\n\n{2} 计算通知',
