  Invoices: '发票',
  ipo: 'IPO',
  'IPO checklist item: EU users served from an EU region.':
    'IPO检查清单项：欧盟用户需来自欧盟地区。',
  'IPO checklist item.': 'IPO检查清单项。',
  'IPO checklist item. Audit findings get fixed before they reset anything.':
    '首次公开募股检查清单项。审计发现的问题在重置任何内容前得到修复。',
  'Is your 4 GB database ready for petabyte scale?': '您的4GB数据库是否已准备好支持PB级规模？',
  'Is your Database person happy?': '您的数据库用户是否满意？',
  'Is your database web scale?': '您的数据库是否支持网络规模扩展？',
  'Issue: {0} over capacity': '问题：{0} 超出容量限制',
  'Issue: errors from {0}': '问题：来自 {0} 的错误',
  'Issue: errors from {0}\nStatus: expected': '问题：来自 {0} 的错误\n状态：预期中',
  "Issue: errors from {0}\nStatus: expected\n\n{1} is restarting, so requests to it fail until it's up. The errors stop on their own.\n\nNo action needed. We're telling you anyway, because telling you is our whole personality.\n{2}":
    '问题：来自 {0} 的错误\n状态：预期中\n\n{1} 正在重启，因此直到它恢复运行前，对该请求的响应会失败。错误会自行消失。\n\n无需采取任何行动。我们仍然告诉您，因为告知您就是我们的全部个性。\n{2}',
  'Issue: PoolExhausted ({0})': '问题：池耗尽 ({0})',
  'Issue: PoolExhausted ({0})\nWhere: {1}\nFirst seen: just now\nLast seen: also just now':
    '问题：池耗尽 ({0})\n位置：{1}\n首次出现：刚刚\n最后出现：也刚刚',
  "Issue: PoolExhausted ({0})\nWhere: {1}\nFirst seen: just now\nLast seen: also just now\n\nEvery worker in the {2} pool is busy, and most are waiting rather than working.\n\nSuggested fixes:\n- Raise the pool\n- Speed up the database\n\nMark as resolved when the pool has room. We'll tell you if it comes back. We always do.\n{3}":
    '问题：池耗尽 ({0})\n位置：{1}\n首次出现：刚刚\n最后出现：也刚刚\n\n{2} 池中的所有工作单元都繁忙，其中大多数正在等待而非工作。\n\n建议修复方法：\n- 增加池容量\n- 加快数据库速度\n\n当池中有可用空间时标记为已解决。如果问题再次出现，我们会通知您。我们总是这样做的。\n{3}',
  'Issue: ThroughputExceeded': '问题：吞吐量超出限制',
  'Issue: ThroughputExceeded\nWhere: {0}\nTrend: escalating':
    '问题：吞吐量超出限制\n位置：{0}\n趋势：持续上升',
  "Issue: ThroughputExceeded\nWhere: {0}\nTrend: escalating\n\nMore requests are reaching {1} than it can push through. That's its limit, not a bug we can point at a line of code for.\n\nWe'll keep counting. Counting is what we do.\n{2}":
    '问题：吞吐量超出限制\n位置：{0}\n趋势：持续上升\n\n更多请求正在到达 {1}，而它无法处理所有请求。这是它的极限，并非我们能指出特定代码行的错误。\n\n我们会继续计数。计数就是我们的工作。\n{2}',
  'It can still do one fifth of a job. Like a meeting that could have been an email.':
    '它仍然能完成五分之一的工作量。就像一场本可以发送电子邮件的会议。',
  'It fills again. Keep reads under {0} ms at the p99 with Burn at ${1}/s or less.':
    '它会再次填满。保持 p99 读取时间低于 {0} 毫秒，开销为 ${1}/s 或更少。',
  'It happened again': '它又出现了',
  "It held for {1} seconds before we said anything. We wanted to be sure. We're sure. We saw it first; now it's your turn.":
    '它保持了 {1} 秒，之后我们才做出回应。我们希望确保万无一失。我们已经确认了。我们最先看到它；现在轮到您了。',
  'It is already down.': '它已经下线。',
  'It is not human.': '这不是人类流量。',
  'It ran phone switches. It can run us.': '它运行了电话交换机功能。它可以为我们运行。',
  'It slows again. Get errors under 1% and hold with Burn at ${0}/s or less.':
    '它再次变慢。错误率需低于 1%，并保持开销为 ${0}/s 或更少。',
  "It took the usual path: it looked easy, then it looked impossible, then it looked done. I'm going with done.":
    '它遵循了常规路径：看起来容易，然后看起来不可能，最后看起来完成了。我选择“完成”。',
  "It went smoother than my last three deploys combined. I'm not going to question it.":
    '这次比我的前三次部署 combined 还要顺利。我将不对此提出疑问。',
  "it worked on my machine. my machine is not where the users are, I'm realising":
    '我的机器上可以运行。但我的机器不是用户所在的地方，我现在才意识到这点',
  'It Works on My Machine': '在我的机器上可以正常运行',
  "It's {0}. Officially on the team as of today.": '现在是 {0}。今天起正式加入团队。',
  "It's {0}. You are receiving this because you are awake.":
    '它是 {0}。您收到此信息是因为您还在清醒状态。',
  "It's {0}. You are receiving this because you are awake.\n\nA query has no index. The Database answers it the hard way: by scanning whole tables.\n\nYou can fix it before you go back to bed. Select the Database and click Add index.\n\nGoodnight, probably.":
    '它是 {0}。您收到此信息是因为您还在清醒状态。\n\n一个查询没有索引。数据库只能通过扫描整个表来回答。\n\n您可以在回睡前修复它。选择数据库并点击添加索引。\n\n晚安，可能吧。',
  "It's a lovely problem to describe and a terrible one to have: people want to buy, and they can't. The Payment Provider is down, so checkouts fail.":
    '这是一个描述起来很美好的问题，但实际存在却很糟糕：人们想要购买，但他们买不到。支付提供商已下线，所以结账失败。',
  "It's fast. It's durable. It's webscale.": '它快速、持久、可扩展。',
  "It's late. We know. You are receiving this because you are awake.":
    '已经很晚了。我们知道。您收到此信息是因为您还在清醒状态。',
  "It's late. We know. You are receiving this because you are awake.\n\n{0} has no idle workers left. They're mostly sitting on open database calls, waiting for answers.\n\nBefore you go looking for a pool size: this runtime doesn't have one. The fix is upstream. Make the database answer faster.\n\nGo back to sleep after. We'll check in.\n{1} on-call":
    '已经很晚了。我们知道。您收到此信息是因为您还在清醒状态。\n\n{0} 已无空闲工作单元。它们大多处于等待数据库响应的开放调用状态。\n\n在您寻找池大小之前：这个运行时间阶段没有池。修复方法在上游。请让数据库更快地响应。\n\n之后回去睡觉吧。我们会跟进。\n{1} 值班中',
  "it's live!!": '它已上线！！',
  "it's live!!\n\n{0}, out in the world. users can poke at it right now\n\nI did the thing where you refresh the page after deploying like it'll change something. it didn't. that's good\n\n{1}":
    '它已上线！！\n\n{0}，正在世界之中。用户现在可以访问它\n\n我做了那个您部署后刷新页面以为会有变化的操作。但并没有。这很好\n\n{1}',
  "It's not a suggestion. Until {2} is researched, {3} is twice as likely to come back. We'd rather not write you this email again, and we suspect you'd rather not read it.":
    '这不是建议。直到 {2} 被研究清楚，{3} 再次出现的可能性是原来的两倍。我们不想再给您发这封邮件，而且我们怀疑您也不想读它。',
  "It's ready whenever you want it. I'll take whatever's next on the list.":
    '你随时都可以获取。我会接接下来列表中的任何一项。',
