  'more: {5}': '更多：{5}',
  'Morning!': '早上好！',
  "Morning!\n\nIt's {0}. Officially on the team as of today.\n\nI have three questions and will probably have thirty by lunch:\n1. Who do I ask about the Database?\n2. Is there a runbook?\n3. Is \"there's no runbook\" the runbook?\n\nVery happy to be here. Let's build something that stays up.\n\n{1}":
    '早上好！\n\n现在是 {0}。今天起正式加入团队。\n\n我有三个问题，到午餐前大概会有三十个吧：\n1. 关于数据库，该向谁提问？\n2. 有应急预案吗？\n3. “没有应急预案”就是应急预案吗？\n\n非常高兴能在这里。让我们构建一个能持续运行的系统。\n\n{1}',
  morph: '形态变化',
