  "No action needed. We're telling you anyway, because telling you is our whole personality.":
    '无需采取任何行动。我们仍然告诉您，因为告知您就是我们的全部个性。',
  "No action needed. We're telling you anyway, because telling you is our whole personality.\n{2}":
    '无需采取任何行动。我们仍然告诉您，因为告知您就是我们的全部个性。\n{2}',
  'No breaker': '无断路器',
