  'No deploy needs rolling back.': '无部署需要回滚。',
  'No disk is full.': '无磁盘已满。',
  "No drama, no surprises, which in this job counts as a celebration. Tests were green; I checked twice because I didn't believe it.":
    '没有意外，也没有惊喜，这在当前任务中算是庆祝。测试通过；我检查了两遍，因为我不相信结果。',
  'No errors': '无错误',
  'No Exits yet': '尚无退出点',
  'No flatline, no fire. Just the narrowest point in the whole thing.':
    '没有平稳线，也没有火苗。这只是整个系统中的最狭窄点。',
  'No framework': '无框架',
  'No funding rounds; Equity stays 100%': '无融资轮次；股权保持100%',
  'No further detail in this alert. {1} is the narrow part of the pipe, and the rest of the Design waits on it.':
    '此警报中无更多细节。{1}是管道中的狭窄部分，设计的其余部分依赖它。',
  'No H100 capacity this month.': '本月没有H100容量。',
  'No incident to report, which is why this email is so short and why nobody woke you up for it.':
    '没有需要报告的事故，因此这封邮件如此简短，也没有人因它叫醒你。',
  'No leaks until the next Feature ships': '直到下一个功能发布前没有泄漏。',
