  'Not yet.': '尚未。',
  'Not you. Them. A flood of junk traffic is hitting your edge, and we are showing them this page a few million times a minute.':
    '不是你。是它们。大量垃圾流量正冲击你的边缘节点，我们每分钟会向它们展示这个页面数百万次。',
  "Note: a replica can't take them": '注意：副本无法接收这些请求',
  'Nothing assigned': '未分配任何内容',
  'Nothing builds a brand like a booth! For a limited time, {0} is offering Startup Alley pods at a founder-friendly rate.':
    '没有什么能像展位一样打造品牌！限时活动，{0} 以创始人友好价格提供 Startup Alley 容器。',
  "Nothing for you to do here, just keeping you in the loop. {0} is restarting. While it is, requests to it will fail. Once it's back up, they'll go through again.":
    '这里没有你的任务，只是让你了解情况。{0} 正在重启。在此期间，对它发出的请求会失败。恢复后，这些请求将再次通过。',
  'Nothing in {0} can be built yet: {1}.': '在 {0} 中目前还不能构建任何东西：{1}。',
  'Nothing is broken. It is just waiting on a spinning thing, figuratively.':
    '没有东西损坏，只是比喻上正在等待一个旋转的东西。',
  'Nothing on your side caused it. Nothing on your side is earning while it lasts, either.':
    '你这边没有造成任何原因。你这边也没有任何能在此期间产生收益的东西。',
  'Nothing on your side: it is their outage. Checkouts come back when it ends.':
    '您这边没有任何操作：这是他们的服务中断。服务结束后，结账流程将恢复。',
  "Nothing personal against your Database. It's just the only one left who knows the answers.":
    '不是针对你的数据库。只是现在只剩下它知道答案。',
  'Nothing runs in the home region.': '本地区域中没有任何运行内容。',
  'Nothing to redo.': '无需重新执行任何操作。',
  'Nothing to ship': '无需发货。',
  'Nothing to undo.': '无需撤销任何操作。',
  'Nothing was served.': '没有提供任何内容。',
  "NOTICE\n\nService: {0}\nStatus: restarting\nImpact: requests to it fail until it's up\nAction required: none\n\nYes, we paged you for something that needs no action. You are receiving this because you are awake.\n{1}":
    '通知\n\n服务：{0}\n状态：正在重启\n影响：直到服务恢复前，相关请求将失败\n所需行动：无\n\n是的，我们已向您发送消息，但无需采取任何行动。您现在看到这条信息是因为您仍在在线。\n{1}',
  'Notice of disclosure, ref. {0}': '披露通知，参考 {0}',
  'Notice of memory exhaustion.': '内存耗尽通知。',
  'Notice of memory exhaustion.\n\nResource {0} hosts both the application and Postgres. Together they have used all of its RAM, and the resource is now swapping.\n\nThe supported configuration is one Postgres per Database: Place a Database and link {1} to it.\n\nWe apologise for any inconvenience. We have not caused any inconvenience; we are just apologising in advance.':
    '内存耗尽通知。\n\n资源 {0} 同时托管了应用和 Postgres。两者已使用完所有 RAM，现正进行换页操作。\n\n支持的配置是每个数据库对应一个 Postgres：请创建一个数据库并将 {1} 与之关联。\n\n我们对此造成的任何不便表示歉意。我们并未造成任何不便，只是提前致歉。',
  'Notice regarding your account balance': '关于您账户余额的通知',
  'Notice.': '通知。',
  "Notice.\n\n{0}'s working set does not fit in RAM anymore, so reads hit disk.\n\nFix: Resize, or the Memory family.\n\nThat is the whole email. We are as surprised as you are.":
    '通知。\n\n{0} 的工作集已无法完全装入 RAM，因此读取操作会访问磁盘。\n\n解决方案：扩大规模，或改用 Memory 系列。\n\n这就是整个邮件内容。我们和您一样感到惊讶。',
  notifications: '通知',
  Notifications: '通知',
