  'On behalf of the team: a hire': '代表团队：招聘一人',
  'On demand': '按需',
  'On IPOs, and on patience': '关于首次公开募股和耐心',
  'On the long arc of your {0}': '关于您{0}的长期路径',
  'On the way to {0}': '通往{0}的路上',
