  One: '一个',
  'One box': '一个盒子',
  'One click fixes the mismatch: click Payments to collect, and the money moves where you can spend it.':
    '点击“支付”即可解决不匹配问题：点击“支付”来收款，钱就会移动到您可以花掉的地方。',
  'One connection carries many requests: 15% less user hop on page views.':
    '一个连接承载大量请求：页面浏览量中用户跳转比例减少15%。',
  'One day someone will ask you to explain your whole system in a single slide. You will be tempted to use forty. Resist.':
    '总有一天，有人会要求你用一张幻灯片解释你的整个系统。你会被诱惑地使用四十张幻灯片。请抵制这种诱惑。',
  'One event loop per core. Uses every core; memory and connections grow with the cores.':
    '每个核心有一个事件循环。使用所有核心；内存和连接随核心数量增长。',
  'One event loop. Waiting costs nothing, but it uses one core, and one slow request stalls every other.':
    '一个事件循环。等待无需成本，但会占用一个核心，而一个缓慢的请求会拖慢其余所有请求。',
  'One flat graph is bad luck. A zone of them is geography.':
    '一个平直的图表是坏运气，而多个区域如此则是地理问题。',
  'One item this week. A query has no index, so the Database scans whole tables to answer it, and the panel shows it.':
    '本周有一个项目。一个查询没有索引，因此数据库需要扫描整个表来回答它，并显示在板块中。',
  'One JVM, 200 threads on every core. Starts at 30% speed and warms for 30 s. Each waiting request holds a thread.':
    '一个JVM，每个核心有200个线程。初始速度为30%，并预热30秒。每个等待请求都会保留一个线程。',
  'One of our customers just told me their {0} invoice is now larger than their cloud bill, their payroll, and their rent combined. They called it "a wake-up call." We called it "a case study."':
    '我们的一个客户刚刚告诉我，他们的{0}发票现在比他们的云账单、工资单和租金总和还大。他们称之为“警钟”。我们则称之为“案例研究”。',
  'One of your alert rules just fired:': '您的一条警报规则刚刚触发：',
  'One of your queries has no index, so every time it runs the Database scans whole tables to find what it needs. Imagine looking up a word by reading the dictionary from "aardvark."':
    '您的一条查询没有索引，因此每次运行时，数据库都会扫描整个表来找到所需内容。想象一下，通过阅读《aardvark》词典来查找一个单词。',
  'One of your queries has no index, so the Database scans whole tables to answer it. That gets slow fast.':
    '您的一条查询没有索引，因此数据库会扫描整个表来回答它。这会很快变慢。',
  'One process per core, 5 threads each. Threads overlap waits; the GVL keeps CPU on one core.':
    '每个核心一个进程，每个进程有5个线程。线程可重叠等待；GVL将CPU保持在单个核心上。',
  'One region': '一个区域',
  'One region forever': '永远只有一个区域',
  'One request that becomes many requests to other services.':
    '一个请求会演变为向其他服务发送的多个请求。',
  'One shard': '一个分片',
  "One task keeps failing. The workers keep retrying it instead of draining the queue, so the line behind it isn't moving.":
    '一个任务持续失败。工作线程不断重试该任务而不是清理队列，导致其后的队列无法移动。',
  'One-click remediation is available for all three. Our universal patcher fixes every vulnerability, including the ones it introduces.':
    '三种情况均可一键修复。我们的通用补丁程序可以修复所有漏洞，包括其引入的漏洞。',
  'Online transaction processing (many small reads and writes) and online analytical processing (few large scans). They need different storage.':
    '在线交易处理（大量小读操作和写操作）和在线分析处理（少量大扫描）。它们需要不同的存储方案。',
  'Only a Cache has an engine.': '只有缓存拥有引擎。',
  'Only a Cache has stampede guards.': '只有缓存拥有防洪流机制。',
  'Only a Cache or Wide-column Store splits keys.': '只有缓存或宽列存储可以分割键。',
  'Only a Connection Pooler has a mode.': '只有连接池具有模式。',
  'Only a Database keeps backups.': '只有数据库可以保留备份。',
  'Only a Database, Pooler, Cache, Search Engine, or Queue keeps a standby.':
    '只有数据库、连接池、缓存、搜索引擎或队列可以保留备用状态。',
  'Only a GPU Node has a GPU type.': '只有GPU节点具有GPU类型。',
  'Only a Load Balancer has a policy.': '只有负载均衡器具有策略。',
  'Only a Load Balancer routes by request kind.': '只有负载均衡器根据请求类型进行路由。',
  'Only a Load Balancer runs health checks.': '只有负载均衡器运行健康检查。',
  'Only a Queue has a dead-letter queue.': '只有队列具有死信队列。',
  'Only a WAF has a paranoia level.': '只有WAF具有警戒级别。',
  'Only a WAF has Under attack mode.': '只有WAF具有“受攻击”模式。',
  'Only a Wide-column Store has quorums.': '只有宽列存储具有多数同意机制。',
  'Only a Wide-column Store or Distributed SQL spreads across regions.':
    '只有宽列存储或分布式SQL可以跨区域分布。',
  'Only an Autoscaler scales.': '只有自动调整器可以进行缩放。',
  'Only Analytics has a sample rate.': '只有分析工具具有采样率。',
  'Only App Servers and Workers run a Stack.': '只有应用服务器和工作者可以运行一个技术栈。',
  'Only App Servers build feeds.': '只有应用服务器可以构建数据流。',
  'Only App Servers compress responses.': '只有应用服务器可以压缩响应。',
  'Only App Servers restart.': '仅应用服务器会重启。',
  'Only App Servers route reads.': '仅应用服务器会路由读取请求。',
  'Only App Servers shed load.': '仅应用服务器会释放负载。',
  'Only DNS, CDNs and Caches have a TTL.': '仅DNS、CDN和缓存有TTL。',
  'Only Go has GOGC.': '仅Go有GOGC。',
  'Only Java runs a choice of collector.': '仅Java可以运行多种收集器。',
  'Only PHP-FPM has a process manager.': '仅PHP-FPM有进程管理器。',
  'Only VMs have an instance family.': '仅虚拟机有实例家族。',
