  'Open {0}: {1}': '打开{0}：{1}',
  'Open a region on another continent. Each region is a tab.':
    '在另一个大陆上打开一个区域。每个区域都是一个标签页。',
  'Open a second region first.': '先打开第二个区域。',
  'Open action item. The incident it prevents is twice as likely until you research it.':
    '打开行动项。你研究它之前，它能预防的意外概率会提高一倍。',
  'Open action items raise odds half as much': '打开行动项会使概率增加一半',
  'Open Research and spend it. Knowledge that sits in a drawer is not knowledge. It is a drawer.':
    '打开“研究”并花掉这些资源。抽屉里的知识不是知识，它只是一个抽屉。',
  'Open Research and spend your Insight.': '开启研究并使用您的洞察。',
  'Open Research and spend your Insight. Pick the thing that bit you most recently. It will bite less.':
    '打开Research并花费您的Insight。选择最近让您印象最深的那件事，它下次会少一些。',
  'Open Research. Spend your Insight. Then return to work.':
    '开启研究。使用你的洞察。然后返回工作。',
  'Open Team': '开放团队',
  "Open Team and I'll bring a whiteboard. Decline and I'll bring it anyway, just to stand next to.":
    'Open Team 和我会带一块白板。Decline 也会带，只是为了站在我旁边。',
  'Open Team if you want to hear the rest of the thought. Decline if you want me to go to sleep.':
    'Open Team，如果你想听我继续说。Decline，如果你想让我去睡觉。',
  "Open Team if you want to talk it through, or Decline and I'll go back to pretending I'm fine.":
    '如果愿意讨论，可以联系开放团队；否则就拒绝吧，我会继续假装自己没事。',
  "Open Team if you're curious. Decline if you've heard enough. I'll still be humming, quietly, in a fault-tolerant way.":
    '如果您感兴趣，可以开放团队讨论。如果您已经听够了，就拒绝吧。我仍然会安静地、以容错方式哼着歌。',
  'Open Team or Decline.': '开放团队或拒绝。',
  'Open Team to discuss, or Decline.': '欢迎打开团队讨论，或拒绝。',
  'Open Team to go through it together, or Decline.': '团队开放讨论，或拒绝。',
  'Open Team to plan it, or Decline.': '开放团队可以规划，或者拒绝。',
  'Open Team to talk it over, or Decline.': '欢迎打开团队讨论，或拒绝。',
  'Open that region first.': '先打开该区域。',
  'Opened {0}': '已打开{0}',
  'Opens in {0}': '在{0}中打开',
  'Opens with the {0} achievement.': '以{0}成就开启。',
  'Opens with your first Exit.': '以您的首次退出开启。',
