  "RFC: Rewrite the app servers in Rust\nAuthor: {0}\nStatus: Extremely proposed\n\nMotivation: fearless concurrency. Also, I'm afraid of our current concurrency.\n\nPlan:\n1. Rewrite.\n2. Celebrate.\n\nEstimate: small. Smaller than you think. Possibly smaller than I think.\n\nRisks: none I'm willing to discuss.\n\nTo discuss anyway, Open Team. To end this, Decline.\n\n{1}":
    'RFC：用Rust重写应用服务器\n作者：{0}\n状态：强烈建议\n\n动机：无畏的并发性。此外，我担心我们当前的并发性。\n\n计划：\n1. 重写。\n2. 庆祝。\n\n估计：很小。比你想象的小。可能比我想象的小。\n\n风险：我愿意讨论的任何风险。\n\n无论如何，请讨论。为结束此操作，拒绝。\n\n{1}',
