  'Your weekly security digest from {0}\n\nNew this week:\n- CVE-2099-0451: Your cache remembers things (CRITICAL)\n- CVE-2099-0452: Your load balancer balances loads (CRITICAL)\n- CVE-2099-0453: You have not run our patcher (CRITICAL)\n\nOne-click remediation is available for all three. Our universal patcher fixes every vulnerability, including the ones it introduces.\n\nPlease run it as root. Running it as a normal user will only partially compromise, um, protect you.':
    '来自 {0} 的每周安全简报\n\n本周新增内容：\n- CVE-2099-0451：您的缓存会记住某些信息（关键）\n- CVE-2099-0452：您的负载均衡器正在平衡负载（关键）\n- CVE-2099-0453：您尚未运行我们的补丁程序（关键）\n\n三种情况均可一键修复。我们的通用补丁程序可以修复所有漏洞，包括其引入的漏洞。\n\n请作为root用户运行。以普通用户运行只会部分降低，嗯，保护您的程度。',
